import{_ as t,a,o,a4 as r}from"./chunks/framework.-FZumj2l.js";const g=JSON.parse('{"title":"Delete a Tax Category","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-settings-tax-category-delete","title":"Delete a Tax Category","description":"Delete a tax category. The category must have no tax rates attached, otherwise the request is refused. The deleted category is returned in the response.","query":"mutation DeleteAdminSettingsTaxCategory($input: deleteAdminSettingsTaxCategoryInput!) {\\n  deleteAdminSettingsTaxCategory(input: $input) {\\n    adminSettingsTaxCategory {\\n      _id\\n      code\\n      name\\n      description\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/settings/tax-categories/33\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminSettingsTaxCategory\\": {\\n      \\"adminSettingsTaxCategory\\": {\\n        \\"_id\\": 33,\\n        \\"code\\": \\"throwaway-del-tc\\",\\n        \\"name\\": \\"Throwaway Del TC\\",\\n        \\"description\\": \\"tmp\\",\\n        \\"message\\": \\"Tax category deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/tax-categories/delete.md","filePath":"api/graphql-api/admin/settings/tax-categories/delete.md","lastUpdated":1783079210000}'),d={name:"api/graphql-api/admin/settings/tax-categories/delete.md"};function n(s,e,i,l,c,h){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="delete-a-tax-category" tabindex="-1">Delete a Tax Category <a class="header-anchor" href="#delete-a-tax-category" aria-label="Permalink to &quot;Delete a Tax Category&quot;">​</a></h1><p>Permanently deletes a tax category. The category must have <strong>no tax rates attached</strong> — attached rates block the deletion.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminSettingsTaxCategory(input:)</code></td><td>Mutation</td><td>Delete a tax category with no attached rates</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td>yes</td><td>Resource path of the category to delete.</td></tr></tbody></table><h2 id="guards" tabindex="-1">Guards <a class="header-anchor" href="#guards" aria-label="Permalink to &quot;Guards&quot;">​</a></h2><p>The delete is refused (returns an <code>errors[]</code> entry, no record removed) when:</p><ul><li>The category still has <strong>one or more tax rates attached</strong> — <em>&quot;This tax category still has tax rates attached and cannot be deleted.&quot;</em> You cannot detach rates through the update mutation either (it requires a non-empty <code>taxrates</code> list). A category becomes deletable only once it has no attached rates (for example, after the underlying tax rates themselves are removed).</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The returned node is an in-memory snapshot of the just-deleted record — its scalar fields (<code>_id</code>, <code>code</code>, <code>name</code>, <code>description</code>) still resolve so you can confirm what was removed.</li><li>Select <strong><code>message</code></strong> for the success confirmation — it resolves to <code>&quot;Tax category deleted successfully.&quot;</code> on a successful delete. <code>message</code> is <code>null</code> on read / list / create / update; a failed delete returns a top-level <code>errors[]</code> entry instead.</li><li>Do <strong>not</strong> select the node&#39;s IRI <code>id</code> field on this mutation — the IRI cannot be generated for a deleted record and the field resolves with an <code>errors[]</code> entry. Select <code>_id</code> instead, as shown.</li><li>Use the <a href="./list.html"><code>adminSettingsTaxCategories</code></a> query to discover valid ids.</li></ul><p>Permissions: <code>settings.taxes.tax_categories.delete</code>. See the <a href="./">Tax Categories overview</a> for behaviour.</p>',12)]))}const p=t(d,[["render",n]]);export{g as __pageData,p as default};
